import java.util.Scanner;
public class CaesarCipher {static String shift(String s,int k){StringBuilder out=new StringBuilder();for(char c:s.toCharArray()){if(c>='A'&&c<='Z')out.append((char)('A'+Math.floorMod(c-'A'+k,26)));else if(c>='a'&&c<='z')out.append((char)('a'+Math.floorMod(c-'a'+k,26)));else out.append(c);}return out.toString();}public static void main(String[]z){Scanner sc=new Scanner(System.in);System.out.print("Enter plaintext: ");String p=sc.nextLine();System.out.print("Enter key: ");int k=sc.nextInt();String c=shift(p,k);System.out.println("Ciphertext: "+c);System.out.println("Decrypted: "+shift(c,-k));}}
